final_template:
AWSTemplateFormatVersion: '2010-09-09'
Description: 'IoT Core policy for device onboarding using Lambda-backed custom resource (note: policy variables not supported in this environment, using wildcard policy)'

Resources:
  LambdaExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: IoTAndLogs
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - iot:CreatePolicy
                  - iot:DeletePolicy
                  - iot:GetPolicy
                  - iot:CreatePolicyVersion
                  - iot:DeletePolicyVersion
                  - iot:SetDefaultPolicyVersion
                  - iot:ListPolicyVersions
                Resource: '*'
              - Effect: Allow
                Action:
                  - logs:CreateLogGroup
                  - logs:CreateLogStream
                  - logs:PutLogEvents
                Resource: 'arn:aws:logs:*:*:*'

  PolicyManagerFunction:
    Type: AWS::Lambda::Function
    Properties:
      Runtime: nodejs22.x
      Handler: index.handler
      Role: !GetAtt LambdaExecutionRole.Arn
      Timeout: 60
      MemorySize: 256
      Code:
        ZipFile: |
          const https = require('https');
          const crypto = require('crypto');
          const { IoTClient, CreatePolicyCommand, DeletePolicyCommand, CreatePolicyVersionCommand, DeletePolicyVersionCommand, SetDefaultPolicyVersionCommand, ListPolicyVersionsCommand } = require('@aws-sdk/client-iot');

          const client = new IoTClient({ region: process.env.AWS_REGION });

          const sendResponse = (event, context, responseStatus, responseData, physicalResourceId, reason) => {
            return new Promise((resolve, reject) => {
              const body = JSON.stringify({
                Status: responseStatus,
                Reason: reason || 'See the details in CloudWatch Log Stream: ' + context.logStreamName,
                PhysicalResourceId: physicalResourceId || context.logStreamName,
                StackId: event.StackId,
                RequestId: event.RequestId,
                LogicalResourceId: event.LogicalResourceId,
                Data: responseData,
              });
              const url = new URL(event.ResponseURL);
              const options = {
                hostname: url.hostname,
                port: 443,
                path: url.pathname + url.search,
                method: 'PUT',
                headers: {
                  'Content-Type': 'application/json',
                  'Content-Length': body.length,
                },
              };
              const req = https.request(options, (res) => {
                console.log(`Response status: ${res.statusCode}`);
                if (res.statusCode >= 200 && res.statusCode < 300) {
                  resolve();
                } else {
                  reject(new Error(`sendResponse failed with status ${res.statusCode}`));
                }
              });
              req.setTimeout(10000, () => {
                req.destroy();
                reject(new Error('sendResponse timed out'));
              });
              req.on('error', (err) => {
                console.error('sendResponse error:', err);
                reject(err);
              });
              req.write(body);
              req.end();
            });
          };

          exports.handler = async (event, context) => {
            console.log('Event:', JSON.stringify(event));
            console.log('ResponseURL:', event.ResponseURL);
            const props = event.ResourceProperties;
            const prefix = props.PolicyNamePrefix || 'DevicePolicy';
            const policyDocument = props.PolicyDocument;

            // Convert policy document object to JSON string
            const policyDocStr = JSON.stringify(policyDocument);
            console.log('Policy document string:', policyDocStr);

            // Truncate prefix to avoid exceeding 128-character policy name limit
            const maxPrefixLen = 100;
            const truncatedPrefix = prefix.length > maxPrefixLen ? prefix.substring(0, maxPrefixLen) : prefix;

            let physicalId = event.PhysicalResourceId;
            let responseData = {};

            try {
              if (event.RequestType === 'Create') {
                const suffix = crypto.randomUUID().split('-').slice(0,2).join('');
                const policyName = `${truncatedPrefix}-${suffix}`;
                await client.send(new CreatePolicyCommand({ policyName, policyDocument: policyDocStr }));
                physicalId = policyName;
                responseData.PolicyName = policyName;
              } else if (event.RequestType === 'Update') {
                const policyName = physicalId;
                // Update policy by creating a new version and setting it as default
                const versions = await client.send(new ListPolicyVersionsCommand({ policyName }));
                const versionIds = versions.policyVersions.map(v => v.versionId);
                if (versionIds.length >= 5) {
                  // Delete the oldest non-default version
                  const nonDefault = versions.policyVersions.filter(v => !v.isDefaultVersion);
                  if (nonDefault.length > 0) {
                    const oldest = nonDefault.reduce((a,b) => a.createDate < b.createDate ? a : b);
                    await client.send(new DeletePolicyVersionCommand({ policyName, policyVersionId: oldest.versionId }));
                  }
                }
                await client.send(new CreatePolicyVersionCommand({ policyName, policyDocument: policyDocStr, setAsDefault: true }));
                responseData.PolicyName = policyName;
              } else if (event.RequestType === 'Delete') {
                const policyName = physicalId;
                if (policyName) {
                  try {
                    await client.send(new DeletePolicyCommand({ policyName }));
                  } catch (err) {
                    // If policy is attached to principals, deletion will fail; log and continue
                    console.log(`Could not delete policy ${policyName}: ${err.message}`);
                  }
                }
              }
              await sendResponse(event, context, 'SUCCESS', responseData, physicalId);
            } catch (err) {
              console.error('Error details:', err.message, err.stack);
              await sendResponse(event, context, 'FAILED', { Error: err.message }, physicalId, err.message);
            }
          };

  PolicyCustomResource:
    Type: AWS::CloudFormation::CustomResource
    DeletionPolicy: Retain
    Properties:
      ServiceToken: !GetAtt PolicyManagerFunction.Arn
      ServiceTimeout: 60
      PolicyNamePrefix: !Ref 'AWS::StackName'
      PolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Action:
              - iot:Connect
              - iot:Publish
              - iot:Subscribe
              - iot:Receive
            Resource: '*'

Outputs:
  PolicyName:
    Description: 'Generated IoT Core policy name'
    Value: !GetAtt PolicyCustomResource.PolicyName

AWSTemplateFormatVersion: "2010-09-09"
Description: "Amazon Verified Permissions Policy Store for Bookstore application"
Parameters:
  AdminExcludedUser:
    Type: String
    Description: "Username of the administrator to be excluded from viewing books"
    Default: "CHANGE-ME-AdminExcludedUser"
    ConstraintDescription: "Must be a non-empty string; replace the default value with an actual username."
  SpecificUser:
    Type: String
    Description: "Username of the specific user permitted to view a specific book"
    Default: "CHANGE-ME-SpecificUser"
    ConstraintDescription: "Must be a non-empty string; replace the default value with an actual username."
  SpecificBook:
    Type: String
    Description: "Book name that the specific user is permitted to view"
    Default: "CHANGE-ME-SpecificBook"
    ConstraintDescription: "Must be a non-empty string; replace the default value with an actual book name."

Resources:
  BookstorePolicyStore:
    Type: AWS::VerifiedPermissions::PolicyStore
    Properties:
      ValidationSettings:
        Mode: STRICT
      Schema:
        CedarJson: |
          {
            "Bookstore": {
              "entityTypes": {
                "Role": {
                  "shape": {
                    "type": "Record",
                    "attributes": {}
                  }
                },
                "User": {
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "yearsAsMember": {
                        "type": "Long"
                      }
                    }
                  },
                  "memberOfTypes": ["Role"]
                },
                "Book": {
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "owningUser": {
                        "type": "Entity",
                        "name": "User"
                      }
                    }
                  }
                }
              },
              "commonTypes": {
                "Context": {
                  "type": "Record",
                  "attributes": {
                    "region": {
                      "type": "String"
                    }
                  }
                }
              },
              "actions": {
                "View": {
                  "appliesTo": {
                    "principalTypes": ["User", "Role"],
                    "resourceTypes": ["Book"],
                    "context": {
                      "type": "Context"
                    }
                  }
                },
                "ViewWithPremiumOffers": {
                  "appliesTo": {
                    "principalTypes": ["User", "Role"],
                    "resourceTypes": ["Book"],
                    "context": {
                      "type": "Context"
                    }
                  }
                }
              }
            }
          }

  PolicyAdminViewAnyBook:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: "permit(principal in Bookstore::Role::\"Admin\", action == Bookstore::Action::\"View\", resource);"

  PolicyForbidExcludedAdmin:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: !Sub "forbid(principal == Bookstore::User::\"${AdminExcludedUser}\", action == Bookstore::Action::\"View\", resource);"

  PolicyPublisherViewOwned:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: "permit(principal in Bookstore::Role::\"Publisher\", action == Bookstore::Action::\"View\", resource) when { resource.owningUser == principal };"

  PolicySpecificUserSpecificBook:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: !Sub "permit(principal == Bookstore::User::\"${SpecificUser}\", action == Bookstore::Action::\"View\", resource == Bookstore::Book::\"${SpecificBook}\");"

  PolicyCustomerViewPremium:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: "permit(principal in Bookstore::Role::\"Customer\", action == Bookstore::Action::\"ViewWithPremiumOffers\", resource) when { principal is Bookstore::User && principal.yearsAsMember >= 2 };"

  PolicyForbidCustomerViewPremium:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: "forbid(principal in Bookstore::Role::\"Customer\", action == Bookstore::Action::\"ViewWithPremiumOffers\", resource) when { principal is Bookstore::User && principal.yearsAsMember < 2 };"

  PolicyForbidNonUSRegion:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: "forbid(principal, action in [Bookstore::Action::\"View\", Bookstore::Action::\"ViewWithPremiumOffers\"], resource) unless { context.region == \"us\" };"

  PolicyStoreIdParameter:
    Type: AWS::SSM::Parameter
    Properties:
      Name: /bookstore/policy-store-id
      Type: String
      Value: !Ref BookstorePolicyStore
      Description: "Policy Store ID for Bookstore application"

Outputs:
  PolicyStoreId:
    Description: "Policy Store ID"
    Value: !Ref BookstorePolicyStore
  PolicyStoreIdParameterName:
    Description: "SSM Parameter name for Policy Store ID"
    Value: !Ref PolicyStoreIdParameter

{
  "Description": "Cognito-based authentication layer for Lex chatbot web UI with IAM roles for Lex V1/V2 and optional live chat API invoke permission.",
  "Parameters": {
    "IdentityPoolName": {
      "Type": "String",
      "Default": "identity pool",
      "Description": "Name of the Cognito identity pool and associated resources"
    },
    "LexV1BotName": {
      "Type": "String",
      "Default": "OrderFlowers",
      "Description": "Name of the Lex V1 bot (used if LexV2BotId is empty)"
    },
    "LexV2BotId": {
      "Type": "String",
      "Default": "",
      "Description": "Lex V2 bot ID (if provided, Lex V2 actions are used)"
    },
    "LexV2BotAliasId": {
      "Type": "String",
      "Default": "",
      "Description": "Lex V2 bot alias ID (required when LexV2BotId is provided)"
    },
    "ForceCognitoLogin": {
      "Type": "String",
      "Default": "false",
      "AllowedValues": ["true", "false"],
      "Description": "When true, denies unauthenticated Lex and live chat API actions"
    },
    "ShouldEnableLiveChat": {
      "Type": "String",
      "Default": "false",
      "AllowedValues": ["true", "false"],
      "Description": "When true, adds execute-api:Invoke permission for the live chat API"
    },
    "LiveChatApiArn": {
      "Type": "String",
      "Default": "",
      "Description": "ARN of the API Gateway endpoint to allow invoke (required when ShouldEnableLiveChat is true)"
    }
  },
  "Conditions": {
    "IsLexV1": {
      "Fn::Equals": [{"Ref": "LexV2BotId"}, ""]
    },
    "IsLexV2": {
      "Fn::Not": [{"Condition": "IsLexV1"}]
    },
    "IsForceLogin": {
      "Fn::Equals": [{"Ref": "ForceCognitoLogin"}, "true"]
    },
    "EnableLiveChat": {
      "Fn::And": [
        {"Fn::Equals": [{"Ref": "ShouldEnableLiveChat"}, "true"]},
        {"Fn::Not": [{"Fn::Equals": [{"Ref": "LiveChatApiArn"}, ""]}]}
      ]
    }
  },
  "Resources": {
    "UserPool": {
      "Type": "AWS::Cognito::UserPool",
      "DeletionPolicy": "Retain",
      "UpdateReplacePolicy": "Retain",
      "Properties": {
        "UserPoolName": {"Ref": "IdentityPoolName"},
        "UsernameAttributes": ["email"],
        "AutoVerifiedAttributes": ["email"],
        "Schema": [
          {"Name": "given_name", "Required": true, "Mutable": true, "AttributeDataType": "String"},
          {"Name": "family_name", "Required": true, "Mutable": true, "AttributeDataType": "String"},
          {"Name": "email", "Required": true, "Mutable": true, "AttributeDataType": "String"},
          {"Name": "preferred_username", "Required": true, "Mutable": true, "AttributeDataType": "String"}
        ],
        "Policies": {
          "PasswordPolicy": {
            "MinimumLength": 8,
            "RequireLowercase": true,
            "RequireUppercase": true,
            "RequireNumbers": true,
            "RequireSymbols": true
          }
        },
        "AccountRecoverySetting": {
          "RecoveryMechanisms": [
            {"Name": "verified_email", "Priority": 1}
          ]
        }
      }
    },
    "UserPoolClient": {
      "Type": "AWS::Cognito::UserPoolClient",
      "Properties": {
        "ClientName": {"Fn::Sub": "${IdentityPoolName}-client"},
        "GenerateSecret": false,
        "UserPoolId": {"Ref": "UserPool"},
        "ExplicitAuthFlows": ["ALLOW_USER_SRP_AUTH", "ALLOW_REFRESH_TOKEN_AUTH"],
        "PreventUserExistenceErrors": "ENABLED"
      }
    },
    "IdentityPool": {
      "Type": "AWS::Cognito::IdentityPool",
      "Properties": {
        "IdentityPoolName": {"Ref": "IdentityPoolName"},
        "AllowUnauthenticatedIdentities": true,
        "CognitoIdentityProviders": [
          {
            "ClientId": {"Ref": "UserPoolClient"},
            "ProviderName": {"Fn::GetAtt": ["UserPool", "ProviderName"]},
            "ServerSideTokenCheck": false
          }
        ]
      }
    },
    "AuthRole": {
      "Type": "AWS::IAM::Role",
      "Properties": {
        "AssumeRolePolicyDocument": {
          "Version": "2012-10-17",
          "Statement": [
            {
              "Effect": "Allow",
              "Principal": {"Federated": "cognito-identity.amazonaws.com"},
              "Action": "sts:AssumeRoleWithWebIdentity",
              "Condition": {
                "StringEquals": {
                  "cognito-identity.amazonaws.com:aud": {"Ref": "IdentityPool"}
                }
              }
            }
          ]
        },
        "Policies": [
          {
            "PolicyName": "AuthRolePolicy",
            "PolicyDocument": {
              "Version": "2012-10-17",
              "Statement": [
                {
                  "Fn::If": [
                    "IsLexV1",
                    {
                      "Effect": "Allow",
                      "Action": ["lex:PostText", "lex:PostContent"],
                      "Resource": {"Fn::Sub": "arn:aws:lex:${AWS::Region}:${AWS::AccountId}:bot:${LexV1BotName}:*"}
                    },
                    {"Ref": "AWS::NoValue"}
                  ]
                },
                {
                  "Fn::If": [
                    "IsLexV2",
                    {
                      "Effect": "Allow",
                      "Action": ["lex:RecognizeText", "lex:RecognizeUtterance"],
                      "Resource": {"Fn::Sub": "arn:aws:lex:${AWS::Region}:${AWS::AccountId}:bot-alias/${LexV2BotId}/${LexV2BotAliasId}"}
                    },
                    {"Ref": "AWS::NoValue"}
                  ]
                },
                {
                  "Effect": "Allow",
                  "Action": ["polly:SynthesizeSpeech"],
                  "Resource": "*"
                },
                {
                  "Fn::If": [
                    "EnableLiveChat",
                    {
                      "Effect": "Allow",
                      "Action": "execute-api:Invoke",
                      "Resource": {"Ref": "LiveChatApiArn"}
                    },
                    {"Ref": "AWS::NoValue"}
                  ]
                }
              ]
            }
          }
        ]
      }
    },
    "UnauthRole": {
      "Type": "AWS::IAM::Role",
      "Properties": {
        "AssumeRolePolicyDocument": {
          "Version": "2012-10-17",
          "Statement": [
            {
              "Effect": "Allow",
              "Principal": {"Federated": "cognito-identity.amazonaws.com"},
              "Action": "sts:AssumeRoleWithWebIdentity",
              "Condition": {
                "StringEquals": {
                  "cognito-identity.amazonaws.com:aud": {"Ref": "IdentityPool"}
                }
              }
            }
          ]
        },
        "Policies": [
          {
            "PolicyName": "UnauthRolePolicy",
            "PolicyDocument": {
              "Version": "2012-10-17",
              "Statement": [
                {
                  "Fn::If": [
                    "IsForceLogin",
                    {"Ref": "AWS::NoValue"},
                    {
                      "Fn::If": [
                        "IsLexV1",
                        {
                          "Effect": "Allow",
                          "Action": ["lex:PostText", "lex:PostContent"],
                          "Resource": {"Fn::Sub": "arn:aws:lex:${AWS::Region}:${AWS::AccountId}:bot:${LexV1BotName}:*"}
                        },
                        {
                          "Effect": "Allow",
                          "Action": ["lex:RecognizeText", "lex:RecognizeUtterance"],
                          "Resource": {"Fn::Sub": "arn:aws:lex:${AWS::Region}:${AWS::AccountId}:bot-alias/${LexV2BotId}/${LexV2BotAliasId}"}
                        }
                      ]
                    }
                  ]
                },
                {
                  "Fn::If": [
                    "EnableLiveChat",
                    {
                      "Fn::If": [
                        "IsForceLogin",
                        {"Ref": "AWS::NoValue"},
                        {
                          "Effect": "Allow",
                          "Action": "execute-api:Invoke",
                          "Resource": {"Ref": "LiveChatApiArn"}
                        }
                      ]
                    },
                    {"Ref": "AWS::NoValue"}
                  ]
                }
              ]
            }
          }
        ]
      }
    },
    "IdentityPoolRoleAttachment": {
      "Type": "AWS::Cognito::IdentityPoolRoleAttachment",
      "Properties": {
        "IdentityPoolId": {"Ref": "IdentityPool"},
        "Roles": {
          "authenticated": {"Fn::GetAtt": ["AuthRole", "Arn"]},
          "unauthenticated": {"Fn::GetAtt": ["UnauthRole", "Arn"]}
        }
      }
    }
  },
  "Outputs": {
    "IdentityPoolId": {
      "Value": {"Ref": "IdentityPool"}
    },
    "UserPoolId": {
      "Value": {"Ref": "UserPool"}
    },
    "UserPoolClientId": {
      "Value": {"Ref": "UserPoolClient"}
    }
  }
}
